class _SessionFileTailer(threading.Thread):
    """Polls a mounted session directory and streams newly appended JSONL events."""

    def __init__(self, session_dir: Path, *, provider: str, events: EventLog, started_at: datetime) -> None:
        super().__init__(daemon=True, name=f"studio-tail-{provider}")
        self.session_dir = session_dir
        self.provider = provider
        self.events = events
        self.started_at = started_at
        self._stop = threading.Event()
        self._offsets: dict[Path, int] = {}

    def stop(self) -> None:
        self._stop.set()
        self.join(timeout=5)

    def run(self) -> None:
        while True:
            stopped = self._stop.wait(0.5)
            try:
                self._drain()
            except OSError:
                pass
            if stopped:
                return

    def _drain(self) -> None:
        if not self.session_dir.exists():
            return
        for path in sorted(self.session_dir.rglob("*.jsonl")):
            if not path.is_file():
                continue
            mtime = datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc)
            if path not in self._offsets and mtime < self.started_at:
                continue
            offset = self._offsets.get(path, 0)
            with path.open("r", encoding="utf-8", errors="replace") as handle:
                handle.seek(offset)
                chunk = handle.read()
                # Only consume complete lines; partial tails are re-read next poll.
                consumed = chunk.rfind("\n") + 1
                if consumed <= 0:
                    continue
                self._offsets[path] = offset + len(chunk[:consumed].encode("utf-8", errors="replace")) if False else offset + consumed
                for line in chunk[:consumed].splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        event = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if isinstance(event, dict):
                        for display in summarize_event(self.provider, event):
                            self.events.append(display)


